def sieve_of_eratosthenes(limit):
    """Sieve of Eratosthenes algorithm to find all primes up to a given limit."""
    sieve = [True] * (limit + 1)
    p = 2
    while (p * p <= limit):
        if sieve[p]:
            for i in range(p * p, limit + 1, p):
                sieve[i] = False
        p += 1
    return [p for p in range(2, limit) if sieve[p]]

