def fibonacci_matrix(n):
    """Construct a 2D matrix that encompasses the initial n x n figures of the Fibonacci sequence, where any member at (i,j) coordinates is the sum of members (i-1, j) and (i, j-1) with base case of i or j being zero resulting in the Fibonacci sequence on the first row and column. n = 10."""
    # Initialize empty nxn matrix
    fib_array = [[0 for _ in range(n)] for _ in range(n)]

    # Compute first 2 elements of fibonacci sequence
    fib_array[0][0] = 0
    if n > 1:
        fib_array[0][1] = 1
        fib_array[1][0] = 1

    # Compute the rest of the first row and column
    for i in range(2, n):
        fib_array[i][0] = fib_array[i - 1][0] + fib_array[i - 2][0]
        fib_array[0][i] = fib_array[0][i - 1] + fib_array[0][i - 2]

    # Compute the other elements of the matrix
    for i in range(1, n):
        for j in range(1, n):
            fib_array[i][j] = fib_array[i - 1][j] + fib_array[i][j - 1]

