def max_subgrid(grid):

    rows = len(grid)
    cols = len(grid[0])

    # Prefix sum computation
    prefix_sum = grid.copy()
    for i in range(rows):
        for j in range(cols):
            if i > 0:
                prefix_sum[i][j] += prefix_sum[i-1][j]
            if j > 0:
                prefix_sum[i][j] += prefix_sum[i][j-1]
            if i > 0 and j > 0:
                prefix_sum[i][j] -= prefix_sum[i-1][j-1]

    # Finding the max sum subgrid
    max_sum = float('-inf')
    max_subgrid = None
    for i in range(rows):
        for j in range(cols):
            for k in range(i, rows):
                for l in range(j, cols):
                    sub_sum = prefix_sum[k][l]
                    if i > 0:
