    prime_numbers.sort() # Sort the list

    # Check if there are k prime numbers
    if len(prime_numbers) < k:
        return "Not enough prime numbers in the array"
    else:
        return prime_numbers[k - 1] # The (k - 1)th index will be the kth smallest prime number

