def sieve_of_eratosthenes(limit):
    primes = [True] * (limit + 1)
    p = 2
    while (p * p <= limit):
        if (primes[p] == True):
            for i in range(p * p, limit + 1, p):
                primes[i] = False
        p += 1
    return [p for p in range(2, limit) if primes[p]]

def find_distinct_primes(start, end):
    primes = sieve_of_eratosthenes(end)
    return sorted(set(prime for prime in primes if start <= prime < end))

