from typing import List

def calculate_distances(num_list: List[int], num: int) -> tuple:
    if len(num_list) == 0 or num not in num_list:
        return (0, 0, 0, 0)

    distances = []
    last_index = -1

    for i, value in enumerate(num_list):
        if value == num:
            if last_index != -1:
                distances.append(i - last_index)
            last_index = i

    total_distance = sum(distances)
    avg_distance = total_distance / len(distances) if distances else 0
    max_distance = max(distances) if distances else 0
    min_distance = min(distances) if distances else 0

    return (total_distance, avg_distance, max_distance, min_distance)
