def find_median(arr):
    n = len(arr)
    if n % 2 == 0:
        return (heapq.nsmallest(n//2, arr) + heapq.nlargest(n//2, arr)) / 2
    else:
        return heapq.nlargest(n//2+1, arr)[0]
