# Define the function to perform inversion on a nested structure
def invert(structure):
    # Iterate over each element in the structure
    for i in range(len(structure)):
        # If the element is a list, recursively invert it
        if isinstance(structure[i], list):
            structure[i] = invert(structure[i])
        # If the element is a dictionary, recursively invert its values
        elif isinstance(structure[i], dict):
            structure[i] = {key: invert(value) for key, value in structure[i].items()}
        # If the element is an integer, invert it by negating it
        elif isinstance(structure[i], int):
            structure[i] = -structure[i]
    return structure
```

