from collections import Counter
MOD = 10**9+7
class Solution:
    def restoreMatrix(self, rowSum: List[int], colSum: List[int]) -> int:
        c = Counter(colSum)
        res = 0
        for r in rowSum:
            for k,v in c.items():
                if v > 0 and r - k >= 0 and r - k & 1 == 0:
                    res += v * (v-1) // 2
                    c[k] -= 1
            if not c:
                break
        return res % MOD
```

