def longest_increasing_subsequence(nums):

    n = len(nums)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    max_length = max(dp)
    subsequence = []

    for i in range(n-1, -1, -1):
        if dp[i] == max_length:
            subsequence.append(nums[i])
            max_length -= 1

    subsequence.reverse()
    return subsequence, len(subsequence)

