def sieve_of_eratosthenes(n):

    if not isinstance(n, int) or n <= 0:
        raise ValueError("n must be a positive integer")

    primes = []
    sieve = [True] * (n + 1)

    for p in range(2, int(n ** 0.5) + 1):
        if sieve[p]:
            for i in range(p * p, n + 1, p):
                sieve[i] = False

    for p in range(2, n + 1):
        if sieve[p]:
            primes.append(p)

    return primes

