class DynamicChecker:
    def __init__(self):
        self.types = {}

    def register_type(self, name, typ):
        self.types[name] = typ

    def check_type(self, func, args, kwargs):
        for arg_name, arg_value in zip(func.__code__.co_varnames[:len(args)], args):
            if arg_name in kwargs:
                arg_value = kwargs[arg_name]
            if arg_name not in self.types:
