            if not isinstance(arg_value, self.types[arg_name]):
                raise TypeError(f"Incorrect type for argument {arg_name}: expected {self.types[arg_name]}, got {type(arg_value)}")

        return True

def put(d: Dict[K, V], k: K, v: V) -> None:
