def find_node(root, value):

    '''This function will search for a node in a binary tree with the given value. 

    Args:
        root (Node): The root node of the binary tree.
        value (int): The value to search.

    Returns:
        Node: The node containing the given value.
    '''
    # Base case: if node is null
    if root is None: 
        return None

    # If the value is the same as root's value
    if root.value == value: 
        return root

    # Recur in the left subtree if the given value is less than root's value 
    elif root.value > value: 
        return find_node(root.left, value)

    # Otherwise recur in the right subtree
    else: 
        return find_node(root.right, value)

