def sort_array(arr):

    m = len(set(arr))
    n = len(arr)

    output = [0] * (n)
    count = [0] * (m)

    for i in range(0, n):
        count[arr[i]] += 1

    for i in range(1, m):
        count[i] += count[i - 1]

    for i in range(n - 1, -1, -1):
        output[count[arr[i]] - 1] = arr[i]
        count[arr[i]] -= 1

    return output

