import string


def base26(x, _alphabet=string.ascii_uppercase):

    result = []
    while x:
        x, digit = divmod(x, 26)
        if not digit:
            x -= 1
            digit = 26
        result.append(_alphabet[digit - 1])
    return ''.join(result[::-1])

