from collections import deque

def traverse_binary_tree_reverse(root):
    if not root:
        return []

    queue = deque([(root, 0)])
    levels = {}
    total_nodes = 0

    while queue:
        node, level = queue.popleft()

        if level not in levels:
            levels[level] = []
        levels[level].append(node.val)

        total_nodes += 1

        if node.left:
            queue.append((node.left, level + 1))
        if node.right:
            queue.append((node.right, level + 1))

    result = []
    for level in sorted(levels.keys(), reverse=True):
        reversed_level = levels[level][::-1]
        avg_value = sum(reversed_level) / len(reversed_level)
        result.append((reversed_level, avg_value))

