def binary_to_hex(binary):

    hex = ""
    binary = binary.zfill((len(binary) // 4 + 1) * 4)

    for i in range(0, len(binary), 4):
        chunk = binary[i:i+4]
        decimal = sum(int(digit) * 2 ** (3 - j) for j, digit in enumerate(chunk))

