def longest_increasing_sequence(arr):
    if not arr:
        return []

    n = len(arr)
    dp = [1] * n  # Initialize DP table with 1s

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    max_length = max(dp)
    end_index = dp.index(max_length) - 1

    sequence = []
    while end_index >= 0:
        sequence.append(arr[end_index])
        end_index -= dp[end_index] - 1

    return sequence[::-1]
```

