def longest_increasing_subsequence(nums):
    if not nums:
        return []

    dp = [1] * len(nums)
    prev = [-1] * len(nums)

    max_length = 0
    max_index = 0

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j] and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1
                prev[i] = j

        if dp[i] > max_length:
            max_length = dp[i]
            max_index = i

    result = []
    while max_index != -1:
        result.append(nums[max_index])
        max_index = prev[max_index]

    return result[::-1]
```

