def zigzag_pattern(m, n):

    result = [[0]*n for i in range(m)]
    current = 1
    go_right = True # flag to switch direction
    for i in range(m):
        if go_right:
            for j in range(n):
                result[i][j] = current
                current += 1
            go_right = False
        else: # go left
            for j in range(n-1, -1, -1):
                result[i][j] = current
                current += 1
            go_right = True
    return result

