# Function to optimize the Fibonacci calculation
def Fibonacci(n, Fib):

    # Check for invalid input
    if n < 0:
        print("Incorrect Input")
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    elif Fib[n] != -1:
        return Fib[n]

    # Calculate the Fibonacci number using memoization
    result = Fibonacci(n-1, Fib) + Fibonacci(n-2, Fib)
    Fib[n] = result

    return result

