def closest_cost(base_costs, topping_costs, target):

    closest = base_costs[0]

    for base in base_costs:
        cost = base

        for i in range(1 << (len(topping_costs) * 2)):
            bit_mask = i

            for j, topping_cost in enumerate(topping_costs):
