def generate_fibonacci(n):

    # Handle the corner case of n being less than or equal to 0
    if n <= 0:
        return []

    # Initialize the list with the first two numbers in the Fibonacci series
    fib_series = [0, 1]

    # Handle the corner case of n being 1
    if n == 1:
        return [0]

    # Handle the corner case of n being 2
    if n == 2:
        return fib_series

    # Generate the remaining numbers in the Fibonacci series
    for i in range(2, n):
        fib_series.append(fib_series[i-1] + fib_series[i-2])

    return fib_series

