import re

def level_to_exp(level):
    ops = {'+': lambda x, y: x + y,
            '-': lambda x, y: x - y,
            '*': lambda x, y: x * y,
            '/': lambda x, y: x / y}
    stack = []
    for token in reversed(re.findall(r'\d+|\D+', level)):
        if token.isdigit():
            stack.append(int(token))
        else:
            b, a = stack.pop(), stack.pop()
            stack.append(ops[token](a, b))
    return stack[0]
```

