import heapq

def find_kth_smallest_distinct_value(nums, k):
    unique_nums = set(nums)
    if len(unique_nums) < k:
        return -1
    min_heap = []
    for num in unique_nums:
        heapq.heappush(min_heap, (num, 1))
    while k > 0:
        num, count = heapq.heappop(min_heap)
        if count == 1:
            return num
        heapq.heappush(min_heap, (num, count - 1))
        k -= 1
```

