    distinct_values = set(nums)
    if len(distinct_values) < k:
        return -1
    min_heap = []
    for num in distinct_values:
        heapq.heappush(min_heap, num)
        if len(min_heap) > k:
            heapq.heappop(min_heap)
    return min_heap[0]
