def mirror_matrix(matrix):

    # determine number of rows and columns
    size = len(matrix)

    # locate middle row
    mid = size//2

    # create mirrored matrix
    mirrored_matrix = []
    for i in range(size):
        newRow = []
        for j in range(size):
             # mirrored elements above and below the diagonal
             if i <= mid:
                 if j < mid - i or j > mid + i:
                     newRow.append(0)
                 else:
                     newRow.append(matrix[i][j])
             else:
                 if j < i - mid or j > mid + mid - i:
                     newRow.append(0)
                 else:
                     newRow.append(matrix[i][j])

        mirrored_matrix.append(newRow)

    return mirrored_matrix

