def find_unpaired(lst):

    # create a dictionary to count numbers frequency
    counts = {}
    for sub in lst:
        for num in sub:
            if num in counts:
                counts[num] += 1
            else:
                counts[num] = 1

    # find the unpaired numbers
    unpaired = [num for num, count in counts.items() if count % 2 != 0]
    return unpaired

