def classify_increase_decrease(arr):

    if arr[0] < arr[1]:
        # Check if the first element is less than the second element
        for i in range(1, len(arr) - 1):
            # Iterate through the list starting from the second element
            if arr[i] > arr[i + 1]:
                # If any element is greater than the next one, the list is not strictly increasing
                return "decreasing"
        # If none of the elements break the increasing pattern, the list is strictly increasing
        return "increasing"
    elif arr[0] > arr[1]:
        # Check if the first element is greater than the second element
        for i in range(1, len(arr) - 1):
            # Iterate through the list starting from the second element
            if arr[i] < arr[i + 1]:
                # If any element is less than the next one, the list is not strictly decreasing
                return "increasing"
        # If none of the elements break the decreasing pattern, the list is strictly decreasing
        return "decreasing"
    else:
        # In case the first two elements are equal, check for discontinuity
        for i in range(1, len(arr) - 1):
            # Iterate through the list starting from the second element
            if arr[i] != arr[i + 1]:
                # If any element is not equal to the next one, the list is discontinuous
                return "discontinuous"
        # If none of the elements break the continuity pattern, the list is dueceasing (all elements are equal)
        return "dueceasing"

