def authenticate_pin(pin):
    if len(pin) != 5 or int(pin[0]) % 2 == 0:
        return False

    digits = [int(digit) for digit in pin]
    if len(set(digits)) < 2:
        return False

    pattern = r'^(?!.*\d{2})((?!\d)(\d)\2)*$'
    if not re.match(pattern, pin):
        return False

    return True
