def unpaired_numbers(my_list):

    # initialize an empty dictionary
    nums_dict = {}

    # go through each element in the list
    for num in my_list:
        # if the number is in the dictionary, increment its count
        # otherwise, initialize its count to 1
        if num in nums_dict:
            nums_dict[num] += 1
        else:
            nums_dict[num] = 1

    # print out the unpaired numbers
    unpaired_nums = [num for num, count in nums_dict.items() if count % 2 == 1]
    return unpaired_nums

