def newton_interpolation(points, x):
    n = len(points)
    coefficients = [points[i][1] for i in range(n)]

    for i in range(1, n):
        for j in range(i, 0, -1):
            coefficients[j-1] = (coefficients[j-1] - coefficients[j]) / (points[j-1][0] - points[j][0])

    return sum(coefficients[i] * (x - points[i][0])**i for i in range(n))
