    has_lowercase = any(c.islower() for c in string)

    if not (has_uppercase and has_lowercase):
        return "Invalid input: String must contain at least one uppercase and one lowercase letter."

    # Construct the palindrome
    if N % 2 == 0:
        # Even length palindrome
        mid_char = string[N//2]
        return mid_char * (N+1)
    else:
        # Odd length palindrome
        left_half = string[:N//2]
        right_half = string[N//2+1:]
        return left_half + right_half[::-1] + left_half[0]
