def find_max(arr):
    """Given a two-dimensional array of integers, identify the highest numerical value present in each sub-array. Additionally, return the index position of the highest value in each sub-array—if multiple highest values exist in a sub-array, return the index of the first occurrence. Your program should handle and validate input restrictions, and ensure that the array and sub-arrays are not empty.

arr = [[8, 1, 10, -1, 4, 9],[3,7,15,5],[21,9,6,-8,14]]"""

reference_output:
def find_max(arr):

    # Check if main array is not empty
    if len(arr) == 0:
        return "Error: The main array is empty."

    max_values = []

    for sub_arr in arr:
        # Check if sub-array is not empty
        if len(sub_arr) == 0:
            return "Error: One or more sub-arrays are empty."
        # Check if sub-array contains only integers
        if not all(isinstance(i, int) for i in sub_arr):
            return "Error: The array should contain only integers."

        max_value = max(sub_arr)
        max_index = sub_arr.index(max_value)
        max_values.append((max_value, max_index))

    return max_values

