        str1 = re.sub('[^A-Za-z]', '', str1).lower()
        str2 = re.sub('[^A-Za-z]', '', str2).lower()
    else:
        str1 = ''.join(filter(str.isalpha, str1))
        str2 = ''.join(filter(str.isalpha, str2))

    common_chars = set(str1) & set(str2)
    return {char: min(str1.count(char), str2.count(char)) for char in common_chars}
