from collections import Counter

def all_palindromic_permutations(s):
    if len(s) % 2 != 0:
        return []

    count = Counter(s)
    odd_count = sum(1 for char, freq in count.items() if freq % 2 != 0)

    if odd_count > 1:
        return []

    result = []
    permute('', count, result)
    return result

def permute(prefix, remaining, result):
    if not remaining:
        result.append(prefix)
        return

    for char, freq in remaining.items():
        if freq == 0:
            continue

        permute(prefix + char, {k: v - 1 for k, v in remaining.items()}, result)
```

