from collections import defaultdict
import heapq

def allocate_resources(data):
    party_priority = defaultdict(int)
    for name, priority, _ in data:
        party_priority[name] = priority

    # Create a min-heap based on party priority
    heap = [(priority, name) for name, priority in party_priority.items()]
    heapq.heapify(heap)

    allocated_resources = {}
    while heap:
        _, name = heapq.heappop(heap)
        if name not in allocated_resources:
            allocated_resources[name] = True

    return list(allocated_resources.keys())
