def merge_dicts(a, b, raise_conflicts=False, path=None):
    if not a:
        return copy.deepcopy(b)
    if not b:
        return copy.deepcopy(a)

    result = {}
    for k in set(a.keys()) | set(b.keys()):
        if k in a and k in b:
            if isinstance(a[k], dict) and isinstance(b[k], dict):
                result[k] = merge_dicts(a[k], b[k], raise_conflicts, path + [k])
            else:
                if raise_conflicts:
                    raise ValueError(f"Conflict at {path}: {a[k]} vs {b[k]}")
                result[k] = b[k]
        elif k in a:
            result[k] = a[k]
        else:
            result[k] = b[k]

    return result
```

