def detectCycle(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow == fast:
            break
    if not fast or not fast.next:
        return None  # No cycle detected
    slow = head
    while slow != fast:
        slow = slow.next
        fast = fast.next
    return slow
