def normalize_dataset(arr):

    avg = sum(arr)/len(arr)
    std_dev = 0
    for x in arr:
        std_dev += (x - avg)*(x - avg)
    std_dev *= (1/len(arr))
    std_dev = std_dev**0.5
    outliers = []
    for i in arr:
        if abs(i - avg) > 2*std_dev:
            outliers.append(i)
    for i in outliers:
        arr.remove(i)
    return arr

