from collections import defaultdict
import heapq

def resource_schedule_optimization(tasks, resources):
    task_resource_map = defaultdict(list)
    for task, resource in tasks:
        task_resource_map[resource].append(task)

    max_utilization = 0
    current_utilization = 0
    resource_heap = []

    for resource in sorted(resources):
        for task in task_resource_map[resource]:
            if len(resource_heap) < len(resources):
                heapq.heappush(resource_heap, (task, 1))
                current_utilization += 1
            else:
                _, count = heapq.heappop(resource_heap)
                if count > 1:
                    heapq.heappush(resource_heap, (task, count - 1))
                    current_utilization -= 1
                else:
                    heapq.heappush(resource_heap, (task, 1))
                    current_utilization += 1
        max_utilization = max(max_utilization, current_utilization)

    return max_utilization
```

