def mesg_index(old, last, new, max_index):

    # print(f'old={old}, new={new}, last={last}, max={max_index}')
    if new >= old:
        # normal case
        if last >= old and last < new:
            return (last - old + 1)
        else:
            return 0
    else:
        # cyclic roll over (new < old)
        if last >= old:
            return (last - old + 1)
        elif last < new:
            return (max_index - old + last)
        else:
